 for d in select * from jsonb_array_elements(c->'departments') loop
 insert into public.icp_departments(id,name) values((d->>'id')::uuid,d->>'name') on conflict(name) do nothing;end loop;
 for p in select * from jsonb_array_elements(c->'programmes') loop
 insert into public.icp_programmes(id,code,name,department_id) select (p->>'id')::uuid,p->>'code',p->>'name',ld.id from public.icp_departments ld where ld.name=(select x->>'name' from jsonb_array_elements(c->'departments') x where x->>'id'=p->>'department_id') on conflict do nothing;end loop;
 for co in select * from jsonb_array_elements(c->'courses') loop
 insert into public.icp_courses(id,code,title,units,is_demo) values((co->>'id')::uuid,co->>'code',co->>'title',(co->>'units')::smallint,false) on conflict do nothing;end loop;
 insert into public.icp_sessions(id,name,is_active) select (x->>'id')::uuid,x->>'name',(x->>'is_active')::boolean from jsonb_array_elements(c->'sessions') x on conflict do nothing;
 insert into public.icp_semesters(id,name) select (x->>'id')::smallint,x->>'name' from jsonb_array_elements(c->'semesters') x on conflict do nothing;
 for m in select * from jsonb_array_elements(c->'mappings') loop
 insert into public.icp_curriculum(programme_id,course_id,session_id,semester_id,year_level) values((m->>'programme_id')::uuid,(m->>'course_id')::uuid,(m->>'session_id')::uuid,(m->>'semester_id')::smallint,(m->>'year_level')::smallint) on conflict do nothing;end loop;
end $import$;
